// GET /api/lesson?story=<slug>&ch=<n> -> {html, status} | 401 {error:"signin"} | 402 {error:"limit", tease, ...status} | 404 | 502
// The chapter text is only in ./_lessons.js (generated by build_newapp.py, bundled into this function, never served as a file).
// Who may read is decided by Supabase, never here: the caller's own Clerk token is forwarded to rpc/lesson_open (chapter 2+, counts a lesson)
// or rpc/lesson_status (chapter 1, free for any signed-in account). Public values only: the project URL and the publishable key (same as app.js).
const SB_URL = "https://azriqynpnbltvxucwmpo.supabase.co", SB_KEY = "sb_publishable_HuWp3C44Bd6dLqGW3DiaxA_qCSpDZZa";
const JUDGE = "SPARK2026";   // the hackathon judge code, already public in app.js/auth.js; the client sends it as x-lv-judge
let LESSONS = null;
const lessons = () => LESSONS || (LESSONS = require("./_lessons.js"));

const send = (res, code, body) => {
  res.statusCode = code;
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.setHeader("Cache-Control", "private, no-store");
  res.setHeader("X-Robots-Tag", "noindex");
  res.end(JSON.stringify(body));
};
const one = d => Array.isArray(d) ? d[0] : d;

async function handler(req, res) {
  if (req.method !== "GET") return send(res, 405, {error: "method"});
  const q = new URL(req.url, "http://x").searchParams, slug = q.get("story") || "", ch = Number(q.get("ch"));
  if (!/^[a-z0-9-]{1,60}$/.test(slug) || !Number.isInteger(ch) || ch < 1) return send(res, 400, {error: "bad request"});
  const L = lessons()[slug], c = L && L[ch - 1];
  if (!c) return send(res, 404, {error: "not found"});
  if (req.headers["x-lv-judge"] === JUDGE) return send(res, 200, {html: c.html, status: {plan: "judge", limit: null}});
  const auth = req.headers.authorization || "";
  if (!/^Bearer [\w.-]{20,}$/.test(auth)) return send(res, 401, {error: "signin"});
  let r;
  try {
    r = await fetch(`${SB_URL}/rest/v1/rpc/${ch === 1 ? "lesson_status" : "lesson_open"}`, {method: "POST",
      headers: {apikey: SB_KEY, Authorization: auth, "Content-Type": "application/json", Accept: "application/json"},
      body: JSON.stringify(ch === 1 ? {} : {p_story: slug, p_chapter: ch})});
  } catch (e) { return send(res, 502, {error: "backend"}); }
  if (r.status === 401 || r.status === 403) return send(res, 401, {error: "signin"});
  if (!r.ok) return send(res, 502, {error: "backend"});
  let d; try { d = one(await r.json()); } catch (e) { return send(res, 502, {error: "backend"}); }
  if (!d || typeof d !== "object") return send(res, 401, {error: "signin"});   // no account behind the token
  if (ch > 1 && d.allowed !== true) return send(res, 402, {error: "limit", tease: c.tease, plan: d.plan, used: d.used, limit: d.limit, resets_at: d.resets_at});
  return send(res, 200, {html: c.html, status: d});
}
module.exports = handler;
